#include "numerics.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <thread>
#include <atomic>
#include <mutex>
using namespace hour_local;
namespace fs=std::filesystem;
const std::vector<std::string> names={"scalar_release","radial_orbit","rod_kick","elastic_mixed","chain_mixed"};
void validate(const fs::path&out){std::ofstream csv(out/"validation.csv");csv<<std::setprecision(16)<<"case,probe,objective_value,objective_gradient,objective_hessian,constraint_value,constraint_gradient,constraint_hessian,passed\n";
 for(const auto&name:names){auto c=make_case(name);double E=std::max(1e-8,energy(c.model,c.initial)-minimum_energy(c.model));Problem p(c.model,c.initial,1./60,E);for(int sample=0;sample<4;++sample){V z=p.initial();for(int i=0;i<z.size();++i)z[i]+=.03*sample*std::sin(i*1.7+.3);auto e=p.evaluate(z),a=p.oracle(z);double f=std::abs(e.objective.a-a.objective.a),g=(e.objective.g-a.objective.g).cwiseAbs().maxCoeff(),H=(e.objective.H-a.objective.H).cwiseAbs().maxCoeff(),cv=(residuals(e)-residuals(a)).cwiseAbs().maxCoeff(),cg=(jacobian(e)-jacobian(a)).cwiseAbs().maxCoeff(),ch=0;for(int i=0;i<int(e.rows.size());++i)ch=std::max(ch,(e.rows[i].value.H-a.rows[i].value.H).cwiseAbs().maxCoeff());bool pass=std::max({f,g,H,cv,cg,ch})<1e-10;csv<<name<<','<<sample<<','<<f<<','<<g<<','<<H<<','<<cv<<','<<cg<<','<<ch<<','<<pass<<'\n';if(!pass)throw std::runtime_error("analytic_AD_mismatch_"+name);}}
 std::cout<<"20 analytic derivative comparisons pass\n";
}
struct Job{std::string id,scenario;Case c;Options options;double h=1./60;int steps=60;};
void run(const fs::path&out,const std::string&mode){fs::create_directories(out/"traces");std::vector<Job>jobs;
 if(mode=="small"||mode=="small_stable")for(const auto&name:names)for(std::string scenario:{"nominal","stiff10"}){if(name=="rod_kick"&&scenario!="nominal")continue;auto c=make_case(name,scenario=="stiff10"?10:1);for(auto o:small_options()){if(mode=="small_stable"){if(o.solver!="AL")continue;o.stable=true;o.id+="_stable";}jobs.push_back({mode+"_"+std::to_string(jobs.size()),scenario,c,o,1./60,60});}if(mode=="small_stable")for(std::string partition:{"edge_full","global"}){Options o;o.id="AL_"+partition+"_stable";o.solver="AL";o.budget=512;o.rho=100;o.partition=partition;o.stable=true;jobs.push_back({mode+"_"+std::to_string(jobs.size()),scenario,c,o,1./60,60});}}
 if(mode=="chains"||mode=="chain_smoke")for(int N:{2,8,32})for(std::string scenario:{"nominal","stiff10","mass10"}){if(mode=="chain_smoke"&&scenario!="nominal")continue;auto c=chain_case(N,scenario=="stiff10"?10:1,scenario=="mass10"?10:1);std::vector<Options>options;
     for(bool warm:{false,true}){options.push_back({std::string("kkt_midpoint_")+(warm?"warm":"cold"),"kkt","midpoint","forward",64,10,warm});for(int budget:{128,512})options.push_back({std::string("AL_")+(warm?"warm_":"cold_")+std::to_string(budget),"AL","midpoint","forward",budget,10,warm});}
     for(bool warm:{false,true})options.push_back({std::string("AL_rhoN_")+(warm?"warm":"cold"),"AL","midpoint","forward",512,10.*N,warm});
     for(const auto&o:options){if(mode=="chain_smoke"&&o.id!="kkt_midpoint_cold"&&o.id!="AL_cold_128")continue;jobs.push_back({mode+"_"+std::to_string(jobs.size()),scenario,c,o,1./60,mode=="chain_smoke"?1:8});}}
 std::ofstream summary(out/(mode+".csv"));summary<<std::setprecision(16)<<"id,case,N,scenario,method,initialization,warm_dual,budget,rho,h,requested_steps,completed_steps,status,inexact_steps,max_primal,max_stationarity,max_energy_error,rms_position,final_error,path_ratio,mean_evaluations,total_evaluations,block_visits,dual_sweeps,regularizations,fallbacks,compute_ms,first_objective,first_curvature\n";
 std::ofstream steps(out/(mode+"_steps.csv"));steps<<std::setprecision(16)<<"id,step,time,converged,reason,primal,stationarity,objective,evaluations,visits,sweeps,energy_error,position_error\n";
 std::mutex mutex;std::atomic<int>next{0};std::vector<std::thread>workers;
 for(int worker=0;worker<4;++worker)workers.emplace_back([&](){for(;;){int index=next.fetch_add(1);if(index>=int(jobs.size()))break;const auto&job=jobs[index];const auto&m=job.c.model;State s=job.c.initial,reference=s;V dual;double E0=energy(m,s),E=std::max(1e-8,E0-minimum_energy(m)),maxP=0,maxS=0,maxE=0,error=0,path=0,refpath=0,ms=0,firstObjective=0,firstCurvature=0;int complete=0,bad=0,evals=0,visits=0,sweeps=0,reg=0,fallback=0;std::string status="completed";
     std::ofstream trace(out/"traces"/(job.id+".csv"));trace<<std::setprecision(16)<<"time,energy,reference_energy";for(int k=0;k<dof(m);++k)trace<<",x"<<k<<",v"<<k<<",ref_x"<<k<<",ref_v"<<k;trace<<'\n';auto write=[&](double t){trace<<t<<','<<energy(m,s)<<','<<energy(m,reference);for(int k=0;k<dof(m);++k)trace<<','<<s.x[k]<<','<<s.v[k]<<','<<reference.x[k]<<','<<reference.v[k];trace<<'\n';};write(0);
     for(int step=0;step<job.steps;++step){try{Problem p(m,s,job.h,E);auto sol=solve(p,job.options,job.options.warm&&dual.size()?&dual:nullptr);State current=p.state(sol.z),refnext=reference_step(m,reference,job.h,64);evals+=sol.evaluations;visits+=sol.visits;sweeps+=sol.sweeps;reg+=sol.regularizations;fallback+=sol.fallback;ms+=sol.milliseconds;maxP=std::max(maxP,sol.primal);maxS=std::max(maxS,sol.dual_residual);if(!sol.converged)++bad;if(!step){firstObjective=sol.objective;if(sol.converged)firstCurvature=reduced_curvature(p,sol);}
         if(!finite(current)){status="nonfinite";break;}double ee=std::abs(energy(m,current)-E0)/E;if(ee>1e4||current.x.norm()>1e6||current.v.norm()>1e6){status="runaway";break;}double err=(current.x-refnext.x).norm()/std::sqrt(m.count);error+=err*err;maxE=std::max(maxE,ee);path+=(current.x-s.x).norm();refpath+=(refnext.x-reference.x).norm();dual=sol.dual;s=std::move(current);reference=std::move(refnext);++complete;write(complete*job.h);
         std::ostringstream row;row<<std::setprecision(16)<<job.id<<','<<step<<','<<complete*job.h<<','<<sol.converged<<','<<sol.reason<<','<<sol.primal<<','<<sol.dual_residual<<','<<sol.objective<<','<<sol.evaluations<<','<<sol.visits<<','<<sol.sweeps<<','<<ee<<','<<err<<'\n';{std::lock_guard<std::mutex>lock(mutex);steps<<row.str();}
     }catch(const std::exception&e){status=e.what();break;}}
     if(status=="completed"&&bad)status="completed_inexact";std::ostringstream row;row<<std::setprecision(16)<<job.id<<','<<job.c.name<<','<<m.count<<','<<job.scenario<<','<<job.options.id<<','<<job.options.initial<<','<<job.options.warm<<','<<job.options.budget<<','<<job.options.rho<<','<<job.h<<','<<job.steps<<','<<complete<<','<<status<<','<<bad<<','<<maxP<<','<<maxS<<','<<maxE<<','<<(complete?std::sqrt(error/complete):0)<<','<<(s.x-reference.x).norm()/std::sqrt(m.count)<<','<<(refpath?path/refpath:0)<<','<<(complete?double(evals)/complete:0)<<','<<evals<<','<<visits<<','<<sweeps<<','<<reg<<','<<fallback<<','<<ms<<','<<firstObjective<<','<<firstCurvature<<'\n';std::lock_guard<std::mutex>lock(mutex);summary<<row.str();summary.flush();steps.flush();std::cout<<job.id<<' '<<job.c.name<<' '<<job.options.id<<' '<<status<<" bad="<<bad<<" ms="<<ms<<'\n';
 }});for(auto&t:workers)t.join();std::cout<<mode<<" complete: "<<jobs.size()<<" runs\n";
}
int main(int argc,char**argv){try{std::string mode=argc>1?argv[1]:"validate";fs::path out=argc>2?argv[2]:"results";fs::create_directories(out);if(mode=="validate")validate(out);else run(out,mode);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
